export function FactsPanel(a){const s=a.keyFacts.map(s=>`\n    <li class="fact-item">\n      <span class="fact-bullet" style="background: ${a.color}"></span>\n      <span class="fact-text">${s}</span>\n    </li>`).join("");return`<div class="facts-panel" data-id="${a.id}">\n    <div class="facts-panel-header">\n      <h3>${a.name}</h3>\n      <span class="facts-badge" style="background: ${a.color}">${a.built}</span>\n    </div>\n    <ul class="facts-list">\n      ${s}\n    </ul>\n    <div class="facts-meta">\n      <div class="facts-meta-item">\n        <span class="meta-label">City</span>\n        <span class="meta-value">${a.city}</span>\n      </div>\n      <div class="facts-meta-item">\n        <span class="meta-label">State</span>\n        <span class="meta-value">${a.state}</span>\n      </div>\n      <div class="facts-meta-item">\n        <span class="meta-label">Architect</span>\n        <span class="meta-value">${a.architect}</span>\n      </div>\n      <div class="facts-meta-item">\n        <span class="meta-label">Style</span>\n        <span class="meta-value">${a.architecturalStyle}</span>\n      </div>\n    </div>\n  </div>`}